    const charging = !b.enter && !b.dead && s.fireT <= 0 && (b.atkT || 0) < 0.45 && (b.atkT || 0) > 0;
    if (charging && !s.chgSnd) { s.chgSnd = 1; snd('charge', era); }
    if (!charging) s.chgSnd = 0;
